import sys, io
md, hist = sys.argv[1], sys.argv[2]   # CLAUDE.md, CLAUDE-history.md
s = io.open(md, encoding='utf-8').read()
def R(old, new):
    global s
    assert s.count(old) == 1, old[:80]
    s = s.replace(old, new)
R("DK to DL (`f3d80d6`) and DM to DN committed, waiting for her push. |", "DK to DL (`f3d80d6`), DM to DN (`159b27e`) and DO to DP committed, waiting for her push. |")
R("The Toolbox tab is gone (DN, her 21:41 on call 32): the teacher's tabs are Home · Chapters · Books · Printables · Practice; `?view=toolbox` lands on the Home.", "The Toolbox tab is gone (DN, her 21:41 on call 32): the teacher's tabs are Home · Chapters · Books · Printables · Practice; `?view=toolbox` lands on the Home. The dictionary (DO, call 31): an earlier room's term in a step's text is a dotted link on screen, the opener shows 'Bring with you' chips, and the card gives a neutral one-line definition, the room's picture, a way to the room and a one-question quick check (sc/terms31.json, bring31.json). The doll's house lights the room you are in; the placement has an 'I don't know' button, judges by skill inside a floor and marks 'rooms to review' in the house; the Scale finder is one two-octave keyboard for both hands, on the Home's Quick line and in every scales room (DP, calls 34 to 37).")
R("- Push: CX, CY to DC, DD to DF, DG to DJ, DK to DL, and DM to DN (six commits).", "- Push: CX, CY to DC, DD to DF, DG to DJ, DK to DL, DM to DN, and DO to DP (seven commits).")
R("1. Call 31: the dictionary cards (an earlier room's terms, underlined in a step's text and as chips on the opener; a neutral one-line definition, the room's picture, a way to the room, a quick check); two builds. Then call 33: Knowing Your Pieces to Grade 8 and diploma depth, then the attic's piano story. Then the Workbooks, fun first, floor by floor.",
  "1. Call 33: Knowing Your Pieces to Grade 8 and diploma depth, then the attic's piano story. Then the Workbooks, fun first, floor by floor. Then a Pieces shelf (her 22:31) once she says which grade and what for.")
io.open(md, 'w', encoding='utf-8').write(s)
h = io.open(hist, encoding='utf-8').read().split('\n')
idx = [i for i, l in enumerate(h) if l.startswith('| 759 |')]
assert len(idx) == 1 and not any(l.startswith('| 760 |') for l in h)
h[idx[0] + 1:idx[0] + 1] = [
 "| 760 | 2026-10-30 | **The dictionary (Build DO; call 31, her 21:23 'a popup like a dictionary for words learned before', 21:25 'neutral, not the metaphors', 21:41 'go with your recommendation').** DICT_TERMS: 79 terms (sc/terms31.json; id, the room that teaches it, English and Korean names and aliases, one neutral line each way; the metaphors stay inside the rooms), from pulse and bar to syncopation and semiquaver. On screen, inside a chapter, a term from an earlier room (dictEarlier: the room's chapter number lower than this one's) met in a step's words (LbSay, LbPiano's steps, LbRemember, through Gloss / glossNode / glossText; longest alias first; English by word boundary, Korean by substring so 반음계 is matched before 반음) becomes a DictLink: a dotted navy underline, the first time each term appears on a screen page (GlossSeen, one Set per LbScreenPage). A tap opens DictCard (fixed at the foot, DictCtx from the App): the term, chapter and room, the definition, the room's house picture (DictIcon from HOUSE_ICONS), 'Go to the room' (jumpToChapter) and 'Quick check': one question from the room's own chapter check (CheckRun with the room's first check level; 'Got it!' or 'Not yet: the room is one tap away'). The opener (Lesson's head, under the chapter art) shows 'Bring with you': up to four such terms, the ones the chapter's text uses most, baked by scan31.js from every Lesson Book's text into bring31.json (62 chapters; e.g. Scales: semitone, tone, sharp, octave). In print, no links; the opener carries one small line 'Bring with you: semitone (ch. 13) · …' in the QR row, left of the QR (patch792.py: as its own block it took 30px from the opener's picture and the Chords picture re-stacked itself; overflow checked). patch790.py reads terms31.json, bring31.json and terms31.code.js next to it. Test: dict790.js; the full set. |",
]
h[idx[0] + 2:idx[0] + 2] = [
 "| 761 | 2026-10-30 | **The lit room, 'I don't know', rooms to review, and the Scale finder for both hands (Build DP; calls 34 to 37, her 22:26, 22:30 'A', 22:53 and 23:05).** (34) The doll's house: the room you are in has its light on (a warm fill and a radial glow, thglow, under the coral frame; thRoom). (35) CheckRun's dunno prop (the placement passes it): an 'I don't know' button under each question, a miss marked dunno; the result says how many. (36, her A) PLACE_SKILL maps a room to one of four skills (ear, rhythm, reading, keys and scales); placeItems takes a floor's six questions round-robin over the skills present; a floor with 4 of 6 right whose two misses share one skill still climbs ('up a floor, and rhythm rooms to review'); those rooms are saved with the placement (pb_place_v1.review), listed in the result as 'Rooms to review' before 'Missed on the way up', and the house marks each with a coral 'review' pill until the room is done or its check passed (HouseMap view.review from placeReview()). (37) SfHandsKeyboard: one keyboard across the scale's span, right-hand numbers above the keys and left-hand numbers below, thumbs as coral circles, thin navy brackets from one thumb to the next instead of the coloured fills; a black key named only when the scale uses it, spelt for the key (D major: F♯ C♯); keys the scale skips in cream; hands together, one tap is one note (the key lights coral-soft, both hands sound, the left an octave lower), '♪ Up and down' plays the whole scale both hands, Reset. In the dial (ScaleFinderDial, the tool) and in ScaleFinderFree (the lesson step); the old two rows, legend and thumb-stop play are gone. The Home's main screen has a Quick line (Scale finder, Metronome); every scales room (the 13 SF_ROOMS) lists the finder first under 'More to play with' (the words 'More in the toolbox' gone with the tab). Tests: dp791.js (the glow, the button and its count, a one-skill climb with review rooms saved and marked, the keyboard's spelling and tap, the Quick line, the room card); the full set. |",
]
io.open(hist, 'w', encoding='utf-8').write('\n'.join(h))
print('CLAUDE.md and CLAUDE-history.md updated (rows 760 to 761)')
